// Validar Clasificacion MEGA
// Parsea el JSON de respuesta del Clasificador y verifica es_lead_valido

const item = $input.first();
const rawContent = item.json.content;

// Extraer el texto de la respuesta de Anthropic
let responseText = '';
if (Array.isArray(rawContent)) {
    responseText = rawContent[0]?.text || '';
} else if (typeof rawContent === 'string') {
    responseText = rawContent;
}

// Intentar parsear JSON
let clasificacion = null;
let parseError = null;

try {
    // Buscar JSON en la respuesta (puede venir con texto adicional)
    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
          clasificacion = JSON.parse(jsonMatch[0]);
    } else {
          throw new Error('No JSON encontrado en respuesta');
    }
} catch (e) {
    parseError = e.message;
}

// Si hay error de parseo → marcar para Slack alert
if (parseError || !clasificacion) {
    return [{
          json: {
                  valido: false,
                  razon_fallo: 'JSON malformado del Clasificador: ' + (parseError || 'sin datos'),
                  clasificacion: null,
                  _ruta: 'STOP_JSON_ERROR'
          }
    }];
}

// Si es_lead_valido === false → marcar para Slack alert
if (clasificacion.es_lead_valido === false) {
    return [{
          json: {
                  valido: false,
                  razon_fallo: 'Lead no valido segun clasificador. Patron: ' + (clasificacion.patron || 'desconocido'),
                  clasificacion: clasificacion,
                  _ruta: 'STOP_LEAD_INVALIDO'
          }
    }];
}

// Todo OK → pasar clasificacion al siguiente nodo
return [{
    json: {
          valido: true,
          clasificacion: clasificacion,
          _ruta: 'CONTINUAR'
    }
}];

