// Parsea de forma robusta los outputs de los 3 nodos IA
// Tolerante a code blocks, whitespace, texto antes/despues
function safeParseJson(text) {
  if (!text) return null;
  let cleaned = String(text).trim();
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const firstBrace = cleaned.indexOf('{');
    const lastBrace = cleaned.lastIndexOf('}');
    if (firstBrace >= 0 && lastBrace > firstBrace) {
      try { return JSON.parse(cleaned.slice(firstBrace, lastBrace + 1)); }
      catch (e2) { return null; }
    }
    return null;
  }
}

const classifierResp = $('Clasificador MEGA').item.json;
const generatorResp = $('Generador MEGA').item.json;
const validatorResp = $('Validador MEGA').item.json;

const classification = safeParseJson(classifierResp && classifierResp.content && classifierResp.content[0] && classifierResp.content[0].text) || {};
const generation = safeParseJson(generatorResp && generatorResp.content && generatorResp.content[0] && generatorResp.content[0].text) || {};
const validation = safeParseJson(validatorResp && validatorResp.content && validatorResp.content[0] && validatorResp.content[0].text) || {};

if (!Array.isArray(validation.errores_criticos)) validation.errores_criticos = [];
if (!Array.isArray(validation.razones_fallo)) validation.razones_fallo = [];

const usageClassifier = (classifierResp && classifierResp.usage) || {};
const usageGenerator = (generatorResp && generatorResp.usage) || {};
const usageValidator = (validatorResp && validatorResp.usage) || {};

const tokensTotal =
  (usageClassifier.input_tokens || 0) + (usageClassifier.output_tokens || 0) +
  (usageGenerator.input_tokens || 0) + (usageGenerator.output_tokens || 0) +
  (usageValidator.input_tokens || 0) + (usageValidator.output_tokens || 0);


// GUARD: si el Generador no produjo turn_1, descartar el caso explicitamente.
// Causa raiz vista: Generador devuelve JSON malformado, safeParseJson cae al
// fallback {} y el Validador puntua el output sin turn_1 valido (ej. caso
// 96dd766c de rafael211@icloud.com con score=100 y turn_1 vacio).
const _t1 = generation && (generation.turn_1 || generation.turn_2 || '');
if (!_t1 || String(_t1).trim().length === 0) {
  if (!Array.isArray(validation.errores_criticos)) validation.errores_criticos = [];
  validation.errores_criticos = [
    'turn_1 missing or generator output malformed',
    ...validation.errores_criticos
  ];
  validation.score = 0;
  validation.validado = false;
}

return [{
  json: {
    classification: classification,
    generation: generation,
    validation: validation,
    generation_metadata: {
      modelo: (generatorResp && generatorResp.model) || null,
      patron_aplicado: generation.patron_aplicado || null,
      tono_aplicado: generation.tono_aplicado || null,
      hora_propuesta: generation.hora_propuesta || null,
      notas: generation.notas || null,
      tokens: usageGenerator
    },
    models: {
      clasificador: (classifierResp && classifierResp.model) || null,
      generador: (generatorResp && generatorResp.model) || null,
      validador: (validatorResp && validatorResp.model) || null
    },
    tokens_total: tokensTotal,
    parse_ok: {
      classification: !!(classification && (classification.es_lead_valido !== undefined || classification.patron !== undefined)),
      generation: !!generation.turn_1,
      validation: !!validation.checks
    }
  }
}];

