// Index prompts: weighted random pick para A/B testing.
//
// Cambio v2: en vez de elegir UNA versión activa por combo, ahora puede haber
// múltiples versiones activas. Pick weighted random según `traffic_weight`
// (default 100 → si solo hay una, equivale a "siempre esa").
//
// Bifurcación por subgroup (MEGA solo): no_store / has_store / null.
// Fallback en orden: exact match → segment default (subgroup=null) → MEGA + subgroup → MEGA default.

const promptRows = $items().map(i => i.json);
const segmentRaw = ($('Search contacts').first()?.json?.properties?.gtm__avatar_segment)
                || ($('Search contacts').first()?.json?.segmento)
                || 'MEGA';
const segment = String(segmentRaw).trim() || 'MEGA';

const has_known_store = $('Code: Detect store signal').first()?.json?.has_known_store ?? null;
let subgroup_key = null;
if (segment === 'MEGA') {
  if (has_known_store === true) subgroup_key = 'has_store';
  else if (has_known_store === false) subgroup_key = 'no_store';
}

const indexed = {};
indexed._segment_used = segment;
indexed._subgroup_used = subgroup_key;
indexed._has_known_store = has_known_store;
indexed._fallback_used = false;

function weightedPick(items) {
  if (!items || items.length === 0) return null;
  if (items.length === 1) return items[0];
  const total = items.reduce((s, i) => s + (typeof i.traffic_weight === 'number' ? i.traffic_weight : 100), 0);
  if (total <= 0) return items[0];
  let r = Math.random() * total;
  for (const it of items) {
    r -= (typeof it.traffic_weight === 'number' ? it.traffic_weight : 100);
    if (r <= 0) return it;
  }
  return items[items.length - 1];
}

function isMatchAll(ptype, seg, sub) {
  return promptRows.filter(r => r.prompt_type === ptype
    && r.is_active === true
    && r.turn_type === 'turn1'
    && r.segmento === seg
    && (sub === null ? (r.subgroup === null || r.subgroup === undefined || r.subgroup === '') : r.subgroup === sub)
  );
}

const PROMPT_TYPES = ['classifier', 'generator', 'validator'];

for (const ptype of PROMPT_TYPES) {
  let candidates;
  let fallback = false;
  // Orden: exact (segment+subgroup) → segment default → MEGA+subgroup → MEGA default
  candidates = subgroup_key ? isMatchAll(ptype, segment, subgroup_key) : [];
  if (candidates.length === 0) {
    candidates = isMatchAll(ptype, segment, null);
    if (candidates.length > 0) fallback = subgroup_key !== null;
  }
  if (candidates.length === 0 && subgroup_key) {
    candidates = isMatchAll(ptype, 'MEGA', subgroup_key);
    if (candidates.length > 0) fallback = true;
  }
  if (candidates.length === 0) {
    candidates = isMatchAll(ptype, 'MEGA', null);
    if (candidates.length > 0) fallback = true;
  }

  const chosen = weightedPick(candidates);

  if (chosen) {
    indexed[ptype] = {
      id: chosen.id,
      version: chosen.version,
      prompt_system: chosen.prompt_system,
      model: chosen.model,
      temperature: typeof chosen.temperature === 'number' ? chosen.temperature : 0,
      max_tokens: chosen.max_tokens || 2048,
      subgroup: chosen.subgroup || null,
      auto_send_enabled: chosen.auto_send_enabled === true,
      traffic_weight: typeof chosen.traffic_weight === 'number' ? chosen.traffic_weight : 100,
      _used_segment: chosen.segmento,
      _candidate_count: candidates.length,
    };
    if (fallback) indexed._fallback_used = true;
  }
}

return [{ json: indexed }];

// Code: Normalize context — produce setter + thread + lead name normalized.
// Inputs disponibles vía referencias explícitas (NO $json para evitar coupling).
const webhook = $('When Executed by Another Workflow').item.json.body || {};
const hubspot = $('Search contacts').item.json || {};
const mailboxResp = $('Smartlead: Lookup mailbox').first()?.json;
const historyResp = $('Smartlead: Get message history').first()?.json;

// === setter ===
const setter_email = (webhook.from_email || '').toLowerCase().trim();
// La response de /email-accounts puede ser un array directo o un wrapper { data: [...] }
let mailboxItem = null;
if (Array.isArray(mailboxResp)) mailboxItem = mailboxResp[0];
else if (mailboxResp && Array.isArray(mailboxResp.data)) mailboxItem = mailboxResp.data[0];
else if (mailboxResp && mailboxResp.from_name) mailboxItem = mailboxResp;
const setter_name = (mailboxItem && (mailboxItem.from_name || mailboxItem.fromName)) || '';
const setter_first_name = setter_name.split(' ')[0] || '';

// === lead_resolved_name ===
// Prioridad: HubSpot firstname → webhook to_name first word → null. Nunca "Lead" placeholder.
function cleanName(s) {
  if (!s) return null;
  const t = String(s).trim();
  if (!t) return null;
  // Filtro de placeholders evidentes
  const blacklist = ['lead', 'null', 'undefined', 'none', '-', '—', 'n/a', 'na'];
  if (blacklist.includes(t.toLowerCase())) return null;
  return t;
}
const hsFirstName = cleanName(hubspot.properties && hubspot.properties.firstname);
const webhookToName = cleanName((webhook.to_name || '').split(' ')[0]);
const webhookLeadName = cleanName(webhook.lead_name);
const lead_resolved_name = hsFirstName || webhookLeadName || webhookToName || null;

// === thread_messages + thread_summary ===
const rawHistory = (historyResp && historyResp.history) || [];
// Normalizar y limpiar HTML para text legible
function stripHtml(html) {
  if (!html) return '';
  return String(html)
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const thread_messages = rawHistory.map(m => ({
  type: m.type,
  seq: m.email_seq_number,
  time: m.time,
  subject: m.subject || null,
  body_text: stripHtml(m.email_body || '').slice(0, 2000),
}));

// Summary para el prompt: últimos 4 mensajes max, body truncated a 600 chars
const tail = thread_messages.slice(-4);
const thread_summary = tail.length === 0
  ? '(sin historial disponible)'
  : tail.map(m => {
      const dir = m.type === 'SENT' ? '→ Enviado' : '← Reply lead';
      const when = m.time ? m.time.slice(0, 10) : '?';
      const body = m.body_text.slice(0, 600).replace(/\n/g, '\n  ');
      return `${dir} (${when}, seq=${m.seq}):\n  ${body}`;
    }).join('\n\n');

return [{
  json: {
    setter_email,
    setter_name,
    setter_first_name,
    lead_resolved_name,
    thread_messages,
    thread_summary,
  }
}];

// Heurísticas para detectar si el lead TIENE tienda online conocida.
// Output: has_known_store: true | false | null
//   true  → evidencia de tienda
//   false → SOLO si el lead lo dice explícitamente en el reply
//   null  → desconocido (default conservador → routing usa catch-all)
//
// Política revisada 2026-05-12: el detector NO marca false por ausencia de
// evidencia. Antes, "@gmail + sin website en HubSpot" caía como false agresivo
// y dirigía a leads con tienda real al flujo no_store (peligroso si auto-send
// estuviese activo). Ahora false requiere afirmación explícita del lead.

const webhook = $('When Executed by Another Workflow').item.json.body || {};
const hubspot = $('Search contacts').item.json || {};
const props = hubspot.properties || {};

const website = String(props.website || '').toLowerCase();
const industry = String(props.industry || '').toUpperCase();
const leadEmail = String(webhook.sl_lead_email || '').toLowerCase();
const replyText = String((webhook.reply_message && webhook.reply_message.text) || '').toLowerCase();

// Dominios extraídos (del website y del email)
const websiteDomain = website.replace(/^https?:\/\//,'').split('/')[0];
const emailDomain = (leadEmail.split('@')[1] || '');

// Señales positivas (has store)
const websiteHasShopPath = /\/(shop|tienda|store|productos?|carrito|catalogo?|checkout)\b/.test(website);
const websiteIsEcomPlatform = /(myshopify|prestashop|wixsite\.com\/shop|bigcartel|tiendanube|woocommerce|squarespace\.com\/products)/.test(website);
const industryIsRetail = ['APPAREL_FASHION','RETAIL','CONSUMER_GOODS','COSMETICS','FOOD_BEVERAGES','LUXURY_GOODS_JEWELRY'].some(k => industry.includes(k));
const replyHasStore = /(mi tienda|mi shop|mi web|mi tienda online|vendo en|en shopify|en prestashop|mis productos|mi marca|facturo|mi negocio online|vendemos|tenemos productos|nuestra tienda)/.test(replyText);

// NUEVO: el DOMINIO del website o del email contiene palabras-clave de tienda
const domainSignal = /(shop|store|tienda|shoes|wear|hat|boutique|moda|fashion|jewelr|joya|cosmetic|beauty|atelier|brand|skate|surf)/.test(
  websiteDomain + ' ' + emailDomain
);

// Señales negativas (no store) — SOLO desde reply explícito
const replyNoStore = /(no tengo tienda|no la tengo|todav[ií]a no|estoy pensando|quiero montar|quiero empezar|estoy empezando|no he empezado|sin tienda|todavia no|aun no)/.test(replyText);

const emailIsPersonal = /@(gmail|hotmail|yahoo|outlook|icloud|live|me\.com)\./.test(leadEmail);
const corporateEmail = !emailIsPersonal && !!emailDomain;

const positiveCount = [websiteHasShopPath, websiteIsEcomPlatform, industryIsRetail, replyHasStore, domainSignal, corporateEmail].filter(Boolean).length;

let has_known_store;
if (replyNoStore && !replyHasStore) {
  has_known_store = false;          // ÚNICA forma de llegar a false: el lead lo dice
} else if (replyHasStore || websiteIsEcomPlatform || websiteHasShopPath || domainSignal) {
  has_known_store = true;           // señal fuerte (incluido domainSignal)
} else if (positiveCount >= 2) {
  has_known_store = true;           // múltiples señales medias
} else {
  has_known_store = null;           // desconocido (default conservador, va al catch-all)
}

return [{
  json: {
    has_known_store,
    evidence: {
      website, websiteDomain, websiteHasShopPath, websiteIsEcomPlatform,
      emailDomain, emailIsPersonal, corporateEmail,
      industry, industryIsRetail,
      domainSignal,
      replyHasStore, replyNoStore,
      positiveCount,
    }
  }
}];

// Construye el ctx para crear el engagement de email en HubSpot.
const reload = $input.first()?.json || {};
const pipelineId = $('Dry run mode?').item.json.pipeline_id;

// campaign_id: Trigger B usa Resolve campaign_id; Trigger A lo trae en webhook body
let campaign_id = null;
try {
  const rci = $('Resolve campaign_id').first()?.json;
  if (rci) campaign_id = Array.isArray(rci) ? rci[0]?.id : rci.id;
} catch (e) {}
if (!campaign_id) {
  try {
    campaign_id = $('When Executed by Another Workflow').item.json.body?.campaign_id;
  } catch (e) {}
}

const body = reload.turn_1_final || reload.turn_1_generated || '';
const htmlBody = body.split(/\n{2,}/).map(p => '<div>' + p.split('\n').join('<br>') + '</div>').join('<br>');
const setterName = reload.setter_name || '';
const firstName = setterName.split(' ')[0] || '';
const lastName = setterName.split(' ').slice(1).join(' ') || '';

return [{
  json: {
    pipeline_id: pipelineId,
    lead_email: (reload.lead_email || '').toLowerCase(),
    campaign_id: String(campaign_id || ''),
    hubspot_contact_id: reload.hubspot_contact_id,
    setter_email: reload.setter_email,
    setter_first_name: firstName,
    setter_last_name: lastName,
    body_text: body,
    body_html: htmlBody,
  }
}];

