// Cuando el clasificador marca el lead como NO valido, saltamos el
// Generador + Validador. Reconstruimos un objeto compatible con Create a row
// con final_status='auto_rejected' y razon explicita.
//
// Esto evita que el Generador alucine outputs sobre leads no-MEGA o explicitamente
// descartados por el clasificador (caso Nancy/Guillem hoy 2026-05-12).

const item = $input.first().json;
const clasificacion = item.clasificacion || {};
const ruta = item._ruta || 'STOP_UNKNOWN';
const razon = item.razon_fallo || 'lead no valido segun clasificador';

return [{ json: {
  classification: clasificacion,
  generation: { turn_1: null, patron_aplicado: null, tono_aplicado: null, hora_propuesta: null, notas: null },
  validation: {
    score: 0,
    validado: false,
    errores_criticos: ['skip: ' + ruta],
    razones_fallo: [razon],
    checks: {}
  },
  generation_metadata: { skip_reason: ruta },
  models: {
    clasificador: ($('Index prompts').first().json.classifier?.model) || null,
    generador: null,
    validador: null
  },
  tokens_total: 0,
  parse_ok: { classification: true, generation: false, validation: false },
  final_status: 'auto_rejected'
}}];

// Filtra las campañas de Smartlead para el send post-aprobación.
//
// Política de selección (en orden):
//   1. Si la pipeline row tiene campaign_id guardado (caso ideal, post-mayo
//      2026) → usar exactamente esa.
//   2. Si NO está guardado pero solo hay 1 ACTIVE → usar esa.
//   3. Si hay múltiples ACTIVE → matchear por smartlead_thread_id contra el
//      message-history de cada campaña hasta encontrar la que contiene este
//      thread. Si ninguna matchea → primera ACTIVE como último recurso.
//   4. Sin ACTIVE → primera de la lista (mejor enviar a una completed que
//      perder el lead).

const items = $input.all().map(i => i.json);
const row = $('Load row by id').first()?.json || {};
const savedCampaignId = row.campaign_id ? String(row.campaign_id) : null;

// Caso 1: row tiene campaign_id guardado
if (savedCampaignId) {
  const match = items.find(c => String(c.id) === savedCampaignId);
  if (match) return [{ json: match }];
  // Pipeline guardó campaign_id pero ya no existe en la lista actual
  // (caso edge, lead movido manualmente). Devolvemos un objeto sintético
  // con ese id y status ACTIVE para que el send lo intente.
  return [{ json: { id: Number(savedCampaignId), status: 'ACTIVE', name: '(from-pipeline)' } }];
}

// Caso 2-3: fallback a heurística por status ACTIVE + thread match
const active = items.filter(c => (c.status || '').toUpperCase() === 'ACTIVE');
if (active.length === 0) return [{ json: items[0] || {} }];
if (active.length === 1) return [{ json: active[0] }];

// Múltiples ACTIVE: matchear por smartlead_thread_id (stats_id)
const threadId = row.smartlead_thread_id;
const leadId = row.smartlead_lead_id;
if (threadId && leadId) {
  for (const c of active) {
    try {
      const url = 'https://server.smartlead.ai/api/v1/campaigns/' + c.id +
                  '/leads/' + leadId + '/message-history';
      const resp = await this.helpers.httpRequestWithAuthentication.call(
        this, 'smartleadApi',
        { method: 'GET', url: url, json: true }
      );
      const history = (resp && resp.history) ? resp.history : (Array.isArray(resp) ? resp : []);
      if (Array.isArray(history) && history.some(m => m.stats_id === threadId)) {
        return [{ json: c }];
      }
    } catch (e) {
      continue;
    }
  }
}
// Último fallback
return [{ json: active[0] }];

// Defaults para primera respuesta al lead (no hay thread previo en sl_thread_map).
// Garantiza que Create EMAIL se ejecute siempre — con thread vacío HubSpot
// crea un thread nuevo asociado al contacto.

const items = $input.all();
if (items.length > 0) return items;

// Fallback: no hay match en sl_thread_map. Devolvemos 1 item con defaults para
// que el flujo continúe a Create EMAIL en HubSpot.
return [{ json: {
  hs_thread_id: '',
  hs_contact_id: $('Code: Prep HubSpot context').first().json.hubspot_contact_id || null,
  fresh_thread: true,
}}];
